export const getChangeUserMutationOptions = <TError = ErrorType<BadRequestResponse | SignInResponse | NotAllowedResponse | NotFoundResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof changeUser>>, TError,ChangeUserMutationVariables, TContext>, request?: SecondParameter<typeof shopFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof changeUser>>, TError,ChangeUserMutationVariables, TContext> => {

const mutationKey = getChangeUserMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof changeUser>>, ChangeUserMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  changeUser(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ChangeUserMutationResult = NonNullable<Awaited<ReturnType<typeof changeUser>>>
    export type ChangeUserMutationBody = BodyType<UserChange>
    export type ChangeUserMutationError = ErrorType<BadRequestResponse | SignInResponse | NotAllowedResponse | NotFoundResponse>
    export type ChangeUserMutationVariables = {id: number;data: BodyType<UserChange>}

    /**
 * @summary Reset a PIN / password, or turn an account on or off (admin)
 */
export const useChangeUser = <TError = ErrorType<BadRequestResponse | SignInResponse | NotAllowedResponse | NotFoundResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof changeUser>>, TError,ChangeUserMutationVariables, TContext>, request?: SecondParameter<typeof shopFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof changeUser>>,
        TError,
        ChangeUserMutationVariables,
        TContext
      > => {
      return useMutation(getChangeUserMutationOptions(options), queryClient);
    }
